import {lineChart,verticalBars,donutChart,heatmap,cohortTable,stackedBar,formatNumber} from './charts.js';

import {fixture,projectAnalytics,trendProjection,metricKey,metricName,designAddon} from './analytics-adapter.js';
const state={period:'month',metric:'views',audienceMetric:'views',legend:[true,true],point:null,range:'最近 30 天',scope:'全部账号',search:'',plan:new URLSearchParams(location.search).get('capability')!=='current'};
const vm=()=>projectAnalytics(fixture,state);
const fmt=n=>n===null?'—':formatNumber(n);
function sampleItems(key){const data=vm();return {content:data.interactions,topics:data.accountRanking,sources:data.platformShare,devices:designAddon.devices}[key]}
let ui;
const view=()=>location.hash.split('/')[1]==='audience'?'audience':'overview';
const trend=(metric=state.metric,legend=state.legend)=>trendProjection(vm(),metric,state.period,legend);
const changeLabel=key=>{const n=vm().changeToday(key);return n===null?'—':(n>=0?'↑ ':'↓ ')+Math.abs(n).toFixed(1)+'%'};
const note=()=>`<span class="red-dot"></span>${state.plan?'补充方案预览 · 新增统计为视觉样例':'现有接口映射 · 缺少来源的统计保留空态'} · ${fixture.today} · 今日覆盖 ${vm().coverage.recorded} / ${vm().coverage.total}<span>${state.scope} / ${state.range}</span>`;
const panelClass=()=>state.plan?'':' backend-unavailable';
const multiTrend=()=>{const data=vm(),indices=Array.from({length:6},(_,i)=>Math.round(i*(data.labels.length-1)/5));return {labels:indices.map(i=>data.labels[i].slice(5).replace('-','/')),series:['plays','exposures','interactions'].map((key,i)=>({name:['播放','曝光','互动'][i],values:indices.map(index=>data.series(key)[index]),color:i}))}};
function cardHeader(title,sub='',action=''){return `<header class="stat-header"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</header>`}
function metricCard(label,value,change,metric,iconName='grid'){return `<button class="metric-card ${state.metric===metric?'selected':''}" data-metric="${metric}" aria-pressed="${state.metric===metric}"><div><span>${label}</span><span class="metric-icon">${ui.icon(iconName)}</span></div><strong>${value}</strong><small><span class="badge">${change}</span> 今日 / 昨日</small></button>`}
function rangeSelect(){return `<select class="range-select" aria-label="统计时间范围" data-analytics-range>${['最近 7 天','最近 30 天','最近 90 天'].map(s=>`<option ${state.range===s?'selected':''}>${s}</option>`).join('')}</select>`}
function sectionNav(){return `<aside class="analytics-aside" aria-label="数据中台导航"><div class="analytics-brand"><span class="red-dot"></span><strong>数据中台</strong><small>DATA INTELLIGENCE</small></div><div class="analytics-nav-label">分析视图</div><nav><a href="#analytics/overview" ${view()==='overview'?'aria-current="page"':''}>${ui.icon('grid')}数据总览</a><a href="#analytics/audience" ${view()==='audience'?'aria-current="page"':''}>${ui.icon('spark')}分析视图</a></nav><div class="analytics-nav-label">数据范围</div><label class="analytics-scope">账号范围<select aria-label="选择数据范围" data-analytics-scope><option ${state.scope==='全部账号'?'selected':''}>全部账号</option><option ${state.scope==='品牌账号'?'selected':''}>品牌账号</option></select></label><div class="analytics-nav-label">相关工作</div><nav><a href="#content">${ui.icon('folder')}查看资料与成果</a><a href="#studio">${ui.icon('file')}回到项目工作区</a></nav><div class="analytics-aside-bottom"><span class="badge">UI 设计实验</span><p>图表使用固定示例数据。<br>未接入统计或实时服务。</p><button class="text-link" data-analytics-action="source">数据口径 ${ui.icon('arrow')}</button></div></aside>`}
export function renderAnalytics(helpers){ui=helpers;return `<div class="page analytics"><div class="analytics-frame">${sectionNav()}<div class="analytics-main"><div class="analytics-breadcrumb">数据中台 ${ui.icon('chevron')} 内容观察 ${ui.icon('chevron')} <strong>${view()==='overview'?'数据总览':'分析视图'}</strong></div><div class="analytics-toolbar"><nav aria-label="分析视图"><a href="#analytics/overview" ${view()==='overview'?'aria-current="page"':''}>数据总览</a><a href="#analytics/audience" ${view()==='audience'?'aria-current="page"':''}>分析视图</a></nav><div class="analytics-tools"><label class="searchbox">${ui.icon('search')}<input type="search" aria-label="搜索统计内容" data-analytics-search value="${ui.esc(state.search)}" placeholder="搜索观察内容…"></label>${rangeSelect()}<select aria-label="选择能力预览" data-analytics-plan><option value="plan" ${state.plan?'selected':''}>补充方案</option><option value="current" ${!state.plan?'selected':''}>现有能力</option></select><button class="btn" data-analytics-action="export">${ui.icon('download')}导出</button></div></div><div class="analytics-sample-note">${note()}</div><div id="analytics-body">${view()==='overview'?overview():audience()}</div>${ui.footer()}</div></div></div>`}

function overview(){const total=sampleItems('content').reduce((n,a)=>n+a.value,0);return `<div class="metrics-row">${metricCard('今日曝光量',fmt(vm().todayMetrics.exposures),changeLabel('exposures'),'samples')}${metricCard('今日播放量',fmt(vm().todayMetrics.plays),changeLabel('plays'),'views','image')}${metricCard('今日互动量',fmt(vm().todayMetrics.interactions),changeLabel('interactions'),'interactions','spark')}<div class="metric-card metric-static"><div><span>今日净增粉丝</span><span class="metric-icon">${ui.icon('folder')}</span></div><strong>${fmt(vm().todayMetrics.netFollowers)}</strong><small><span class="badge">阶段快照</span> 截至 10:24</small></div></div><section class="stat-card analysis-card">${cardHeader('内容趋势分析','观察不同周期的变化，让数据回到创作判断。',`<div class="period-switch" role="group" aria-label="趋势周期">${[['day','日'],['month','月'],['year','年']].map(([id,label])=>`<button data-period="${id}" aria-pressed="${state.period===id}">${label}</button>`).join('')}</div>`)}<div class="chart-legend" role="group" aria-label="趋势图例">${['当前周期','对比周期'].map((s,i)=>`<button data-series="${i}" aria-pressed="${state.legend[i]}"><i style="background:var(--series-${i+1})"></i>${s}</button>`).join('')}</div><div id="main-trend">${lineChart({id:'overview',...trend(),height:265,area:true})}</div><div class="chart-summary" aria-live="polite">${state.range} · ${metricName(state.metric)} · ${state.period==='day'?'最近12个日度点':state.period==='year'?'按月聚合已有记录':'完整日度序列'} · 固定契约样例${vm().hasMissing?' / 含曝光缺失':''}</div></section><div class="overview-bottom"><section class="stat-card content-ranking">${cardHeader('互动构成','CONTENT PERFORMANCE',rangeSelect())}<div class="stat-total">${formatNumber(total)}<small><span class="badge green">所选周期</span> 互动构成合计</small></div>${stackedBar(sampleItems('content'))}<div id="ranking-list">${contentRows()}</div></section><section class="stat-card">${cardHeader('账号播放排行','TOP CONTENT TOPICS',rangeSelect())}<div class="stat-total">${formatNumber(sampleItems('topics').reduce((n,a)=>n+a.value,0))}<small><span class="badge green">所选周期</span> 账号播放合计</small></div><div class="horizontal-bars">${sampleItems('topics').map((a,i)=>`<button data-chart-detail="${a.label}：${formatNumber(a.value)} 次观察（示例）"><div><span>${a.label}</span><strong>${formatNumber(a.value)} <small>${(a.value/sampleItems('topics').reduce((n,a)=>n+a.value,0)*100).toFixed(1)}%</small></strong></div><div class="horizontal-track"><i style="width:${a.value/sampleItems('topics')[0].value*100}%;background:var(--series-${Math.min(i+1,5)})"></i></div></button>`).join('')}</div></section><section class="stat-card">${cardHeader('平台播放贡献','SOURCE DISTRIBUTION',`<button class="icon-btn" data-analytics-action="source" aria-label="查看来源口径">${ui.icon('more')}</button>`)}${donutChart(sampleItems('sources'),{title:'平台播放贡献扇形环图',center:formatNumber(sampleItems('sources').reduce((n,a)=>n+a.value,0)),subtitle:'平台播放 · 示例',callouts:true})}</section></div>`}

function contentRows(){const found=sampleItems('content').filter(a=>a.label.includes(state.search));return found.length?found.map((a,i)=>`<button class="ranking-row" data-chart-detail="${a.label}：${formatNumber(a.value)} · 演示聚合"><i style="background:var(--series-${Math.min(i+1,5)})"></i><span>${a.label}</span><strong>${formatNumber(a.value)} <small>${(a.value/sampleItems('content').reduce((n,a)=>n+a.value,0)*100).toFixed(0)}%</small></strong></button>`).join(''):'<div class="analytics-empty">没有匹配的观察内容<button class="text-link" data-analytics-action="reset-search">清除搜索</button></div>'}

function audience(){const d=trend(state.audienceMetric,[true,true]);return `<div class="audience-top"><section class="stat-card audience-trend"><div class="inline-metrics">${[['views','今日播放量',fmt(vm().todayMetrics.plays),changeLabel('plays')],['samples','今日曝光量',fmt(vm().todayMetrics.exposures),changeLabel('exposures')],['interactionRate','今日互动量',fmt(vm().todayMetrics.interactions),changeLabel('interactions')],['duration','今日净增粉丝',fmt(vm().todayMetrics.netFollowers),changeLabel('netFollowers')]].map(([id,label,value,change])=>`<button data-audience-metric="${id}" aria-pressed="${state.audienceMetric===id}"><span>${label}</span><strong>${value}</strong><small>${change} / 昨日</small></button>`).join('')}</div><div id="audience-trend-chart">${lineChart({id:'audience',labels:d.labels,series:d.series.map((s,i)=>({...s,dashed:i===1})),height:290,compact:true})}</div><div class="stat-card-footer">${rangeSelect()}<button class="text-link" data-analytics-action="trend-detail">趋势明细 ${ui.icon('arrow')}</button></div></section><section class="stat-card heat-card${panelClass()}">${cardHeader('时段热力图',state.plan?'补充采集方案 · 视觉样例':'来源未接入',`<button class="icon-btn" data-analytics-action="heat-detail" aria-label="热力图说明">${ui.icon('more')}</button>`)}${heatmap()}</section><section class="stat-card activity-card">${cardHeader('日度数据快照','数据截至 10:24 · 阶段快照')}<strong class="activity-total">${fmt(vm().todayMetrics.plays)}</strong><p>最近 16 日日度播放 · 固定契约样例</p>${verticalBars({values:vm().series('plays').slice(-16),labels:vm().labels.slice(-16),title:'日度播放垂直柱状图'})}<div class="activity-list"><span>关联运营内容</span>${vm().contents.map(c=>`<button data-analytics-content="${c.id}"><span>${c.title}</span><strong>${{REVIEW:'待审核',READY:'待发布',EDITING:'制作中'}[c.stage]}</strong></button>`).join('')}</div><div class="stat-card-footer"><button class="text-link" data-analytics-action="activity-detail">查看观察快照 ${ui.icon('arrow')}</button></div></section></div><div class="audience-bottom"><section class="stat-card cohort-card${panelClass()}">${cardHeader('留存矩阵',state.plan?'补充采集方案 · 视觉样例':'来源未接入',`<button class="icon-btn" data-analytics-action="cohort-detail" aria-label="留存矩阵说明">${ui.icon('more')}</button>`)}${cohortTable()}<div class="cohort-note">矩阵值为视觉示例，非真实用户留存。<br>尚未形成的周期保持空档。</div><div class="stat-card-footer"><span>最近 6 周</span><button class="text-link" data-analytics-action="cohort-detail">分组明细 ${ui.icon('arrow')}</button></div></section><section class="stat-card active-trend-card">${cardHeader('播放 / 曝光 / 互动走势','MULTI-PERIOD TRENDS',`<button class="icon-btn" data-analytics-action="active-detail" aria-label="活跃趋势说明">${ui.icon('more')}</button>`)}<div class="multi-trend">${lineChart({id:'active',...multiTrend(),height:225,compact:true})}</div><div class="period-stat-list"><div><i style="background:var(--series-1)"></i><span>周期播放</span><strong>${fmt(vm().windowTotals.plays)}</strong></div><div><i style="background:var(--series-2)"></i><span>周期曝光</span><strong>${fmt(vm().windowTotals.exposures)}</strong></div><div><i style="background:var(--series-3)"></i><span>周期互动</span><strong>${fmt(vm().windowTotals.interactions)}</strong></div></div><div class="stat-card-footer">${rangeSelect()}<button class="text-link" data-analytics-action="active-detail">活跃明细 ${ui.icon('arrow')}</button></div></section><section class="stat-card device-card${panelClass()}">${cardHeader('设备构成',state.plan?'补充采集方案 · 视觉样例':'来源未接入',`<button class="icon-btn" data-analytics-action="device-detail" aria-label="设备构成说明">${ui.icon('more')}</button>`)}${donutChart(sampleItems('devices'),{title:'设备构成环形图',center:'100%',subtitle:'示例设备构成',small:true})}<div class="stat-card-footer">${rangeSelect()}<button class="text-link" data-analytics-action="device-detail">设备明细 ${ui.icon('arrow')}</button></div></section></div>`}

function repaint(){const root=document.querySelector('.analytics');if(!root)return;document.querySelector('#analytics-body').innerHTML=view()==='overview'?overview():audience();root.querySelectorAll('[data-analytics-range]').forEach(s=>s.value=state.range);root.querySelectorAll('[data-analytics-plan]').forEach(s=>s.value=state.plan?'plan':'current');root.querySelector('.analytics-sample-note').innerHTML=note();state.point=null}
function detail(title,text){ui.modal(title,`<p class="detail-description">${ui.esc(text)}</p>`, '<button class="btn" data-action="close">关闭</button>')}
function showPoint(target){const root=target.closest('.line-chart');if(!root)return;const id=target.dataset.chartId,index=Number(target.dataset.chartPoint);const t=id==='audience'?trend(state.audienceMetric,[true,true]):trend();let series,labels;if(id==='active'){const multi=multiTrend();labels=multi.labels;series=multi.series}else{labels=t.labels;series=t.series}const tip=root.querySelector('.chart-tooltip');tip.hidden=false;tip.style.left=Math.min(70,Math.max(5,index/Math.max(1,labels.length-1)*80))+'%';tip.innerHTML=`<strong>${labels[index]}</strong>${series.map(s=>`<span><i style="background:var(--series-${s.color+1})"></i>${s.name}<b>${fmt(s.values[index])}</b></span>`).join('')}`;root.querySelectorAll('[data-chart-point]').forEach(p=>p.classList.toggle('chart-point-selected',p===target))}
function exportData(){const rows=[['鑫世界数据中台','同一日度契约样例聚合 / 非实时'],['能力模式',state.plan?'补充方案视觉样例':'现有接口映射'],['视图',view()==='overview'?'数据总览':'分析视图'],['范围',state.scope],['周期',state.range],['内容','观察值'],...sampleItems('content').filter(a=>a.label.includes(state.search)).map(a=>[a.label,a.value])];const csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='鑫世界-数据观察-示例.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);ui.toast('已导出固定示例数据 CSV')}

export function mountAnalytics(){const root=document.querySelector('.analytics');if(!root)return;
  root.addEventListener('click',e=>{const target=e.target.closest('button,[data-chart-point],[data-chart-detail]');if(!target)return;if(target.dataset.metric){state.metric=target.dataset.metric;repaint()}else if(target.dataset.audienceMetric){state.audienceMetric=target.dataset.audienceMetric;repaint()}else if(target.dataset.period){state.period=target.dataset.period;repaint()}else if(target.dataset.series){const i=Number(target.dataset.series);if(state.legend.filter(Boolean).length===1&&state.legend[i])return ui.toast('至少保留一条趋势序列');state.legend[i]=!state.legend[i];repaint()}else if(target.dataset.chartDetail){detail('统计明细 · 示例',target.dataset.chartDetail)}else if(target.dataset.analyticsContent){ui.detail(target.dataset.analyticsContent)}else if(target.dataset.chartPoint){showPoint(target)}else if(target.dataset.analyticsAction){const action=target.dataset.analyticsAction;if(action==='export')return exportData();if(action==='reset-search'){state.search='';root.querySelector('[data-analytics-search]').value='';repaint();return}const copy={source:['数据口径','今日卡片只映射今日快照，范围筛选改变周期图表与聚合。排名、平台构成、互动构成从同一记录计算。补充方案的时段/留存/设备是视觉样例，需要单独数据来源；未修改正式API。完整适配设计见 ANALYTICS-ADAPTATION.md。'], 'trend-detail':['趋势明细','可切换日/月/年，点击指标改变主图序列，图例可隐藏对比周期，悬停或键盘聚焦显示数据点。本轮不连接正式统计。'],'heat-detail':['热力图说明','7 列表示星期，24 行表示小时，颜色深度代表示例观察次数。点击色块可查看具体时段。'],'activity-detail':['日度快照与异常提醒',`今日播放 ${fmt(vm().todayMetrics.plays)}。${vm().alerts.map(a=>a.title+'：'+a.detail).join('；')} 所有值来自固定契约样例，非实时数据。`],'cohort-detail':['分组留存说明','按周排列观察分组，横向为经历的观察周期；空格表示尚未形成数据。此矩阵仅为布局与交互实验。'],'active-detail':['统计口径','播放/曝光/互动来自同一日度样例记录；周期曝光有缺失时合计显示—。不使用系数放大或伪造比较值。'],'device-detail':['设备构成说明','示例：桌面 54.6%、移动 38.7%、平板 6.7%。正式接入需真实设备数据；缺失时保留空态。']};if(copy[action])detail(...copy[action])}});
  root.addEventListener('change',e=>{if(e.target.matches('[data-analytics-plan]')){state.plan=e.target.value==='plan';repaint()}if(e.target.matches('[data-analytics-range]')){state.range=e.target.value;repaint()}if(e.target.matches('[data-analytics-scope]')){state.scope=e.target.value;repaint()}});
  root.addEventListener('input',e=>{if(e.target.matches('[data-analytics-search]')){state.search=e.target.value;if(view()==='overview')root.querySelector('#ranking-list').innerHTML=contentRows();else {const rows=root.querySelectorAll('.activity-list button');rows.forEach(row=>row.hidden=!row.innerText.includes(state.search));}}});
  root.addEventListener('pointerover',e=>{const target=e.target.closest('[data-chart-point]');if(target)showPoint(target)});
  root.addEventListener('focusin',e=>{if(e.target.matches('[data-chart-point]'))showPoint(e.target)});
  root.addEventListener('keydown',e=>{const target=e.target.closest('[data-chart-point],[data-chart-detail]');if(target&&(e.key==='Enter'||e.key===' ')){e.preventDefault();target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});
}
